window.MG_LAZY_DATA["data/lazy/owner-courses/v11-sleipner-ccs-4e83f724fcc7bccc.json"]={sha256:"4e83f724fcc7bccc17e04d0186d068acbf814b89edf7fa22f9282f50a6180bc3",value:{"id":"v11-sleipner-ccs","title":"Sleipner 油氣與碳封存","titleEn":"Sleipner oil/gas and carbon storage","category":"materials","subcategory":"resources-oil","subcategoryTitle":"油氣與海上資源","subcategoryTitleEn":"Oil/gas and offshore resources","learningTrack":"resources","learningSubdiscipline":"resources-oil","learningTags":["resources","resources-oil","sleipner-ccs"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-sleipner","v11x-ccs"],"stages":[{"id":"v11-sleipner-ccs-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在Sleipner 油氣與碳封存案例中比較油氣與CO2物料與井筒完整性概念，各完成分析及驗證。","descriptionEn":"Analyze and validate hydrocarbon/co2 balance and well-integrity concepts within the Sleipner oil/gas and carbon storage case.","steps":[{"id":"v11-sleipner-ccs-v11-01","order":1,"sequence":1,"title":"儲層模型與物料平衡：架構分析","titleEn":"Reservoir models and material balance: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":[],"objective":"針對油氣與CO2物料提出可反駁的儲層模型與物料平衡模型與驗證紀錄。","objectiveEn":"Produce a falsifiable reservoir models and material balance model and evidence record for hydrocarbon/co2 balance.","instruction":"在「Sleipner 油氣與碳封存」的師傅示意與公開來源中，先辨識油氣與CO2物料。油氣儲層需區分孔隙流體、壓力與連通；累計產量與可採資源不同。 建立儲層模型與物料平衡的輸入、狀態、輸出及邊界圖；本課重點是分離、壓縮與封存監測邊界。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。按給定假想數據覈對流入、流出與庫存。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify hydrocarbon/co2 balance in the mentor diagram and primary sources for Sleipner oil/gas and carbon storage. Reservoirs distinguish pore fluids, pressure and connectivity; cumulative production differs from recoverable resources. Draw the inputs, states, outputs and boundaries of reservoir models and material balance, focusing on separation, compression and storage-monitoring boundaries. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Check inflow, outflow and inventory using assumed data. Record units, undisclosed parameters and model breakdown conditions.","observation":"按給定假想數據覈對流入、流出與庫存。","observationEn":"Check inflow, outflow and inventory using assumed data.","failure":"常見誤判：地質資源數量等於可即時開採量。","failureEn":"Common misconception: Geological resources equal immediately producible quantities.","check":"提交油氣與CO2物料的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for hydrocarbon/co2 balance.","knowledge":[{"id":"v11-sleipner-ccs-v11-01-k1","title":"儲層模型與物料平衡","titleEn":"Reservoir models and material balance","text":"油氣儲層需區分孔隙流體、壓力與連通；累計產量與可採資源不同。 本課架構對應：油氣與CO2物料","textEn":"Reservoirs distinguish pore fluids, pressure and connectivity; cumulative production differs from recoverable resources. Course architecture correspondence: Hydrocarbon/CO2 balance","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"按給定假想數據覈對流入、流出與庫存。 應逐項保留基準與不確定度；地質資源數量等於可即時開採量。 是本單元要排除的誤解。","textEn":"Check inflow, outflow and inventory using assumed data. Retain each reference and uncertainty; reject the misconception: Geological resources equal immediately producible quantities.","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想一日液體進料1000 t，油700 t、水280 t、未判明20 t。質量閉合=98%，未判明2%須保留；不能把全部差額直接當洩漏，需核對取樣、庫存與量測。無實際井壓、鑽進或井控操作。","textEn":"Assume daily liquid feed 1000 t, oil 700 t, water 280 t and unassigned 20 t: closure 98%, unresolved 2%. Do not call the entire residual leakage; check samples, inventory and measurements. No well-pressure, drilling or well-control operations are provided.","sourceIds":["v11x-sleipner","v11x-ccs"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就油氣與CO2物料的「儲層模型與物料平衡」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for reservoir models and material balance in hydrocarbon/co2 balance?","options":["油氣儲層需區分孔隙流體、壓力與連通；累計產量與可採資源不同。","地質資源數量等於可即時開採量。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Reservoirs distinguish pore fluids, pressure and connectivity; cumulative production differs from recoverable resources.","Geological resources equal immediately producible quantities.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"油氣儲層需區分孔隙流體、壓力與連通；累計產量與可採資源不同。 按給定假想數據覈對流入、流出與庫存。","explanationEn":"Reservoirs distinguish pore fluids, pressure and connectivity; cumulative production differs from recoverable resources. Check inflow, outflow and inventory using assumed data."}},{"id":"v11-sleipner-ccs-v11-02","order":2,"sequence":2,"title":"儲層模型與物料平衡：證據驗證","titleEn":"Reservoir models and material balance: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-01"],"objective":"針對油氣與CO2物料提出可反駁的儲層模型與物料平衡模型與驗證紀錄。","objectiveEn":"Produce a falsifiable reservoir models and material balance model and evidence record for hydrocarbon/co2 balance.","instruction":"沿用前一步「儲層模型與物料平衡」模型，檢查油氣與CO2物料的兩個假想案例。按給定假想數據覈對流入、流出與庫存。 先訂可接受誤差，再比較預測與獨立計算；區分油氣儲層需區分孔隙流體、壓力與連通；累計產量與可採資源不同。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous reservoir models and material balance model to inspect two hypothetical cases involving hydrocarbon/co2 balance. Check inflow, outflow and inventory using assumed data. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Reservoirs distinguish pore fluids, pressure and connectivity; cumulative production differs from recoverable resources.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"按給定假想數據覈對流入、流出與庫存。","observationEn":"Check inflow, outflow and inventory using assumed data.","failure":"常見誤判：地質資源數量等於可即時開採量。","failureEn":"Common misconception: Geological resources equal immediately producible quantities.","check":"提交油氣與CO2物料的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for hydrocarbon/co2 balance.","knowledge":[{"id":"v11-sleipner-ccs-v11-02-k1","title":"儲層模型與物料平衡","titleEn":"Reservoir models and material balance","text":"油氣儲層需區分孔隙流體、壓力與連通；累計產量與可採資源不同。 本課架構對應：油氣與CO2物料","textEn":"Reservoirs distinguish pore fluids, pressure and connectivity; cumulative production differs from recoverable resources. Course architecture correspondence: Hydrocarbon/CO2 balance","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"按給定假想數據覈對流入、流出與庫存。 應逐項保留基準與不確定度；地質資源數量等於可即時開採量。 是本單元要排除的誤解。","textEn":"Check inflow, outflow and inventory using assumed data. Retain each reference and uncertainty; reject the misconception: Geological resources equal immediately producible quantities.","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想一日液體進料1000 t，油700 t、水280 t、未判明20 t。質量閉合=98%，未判明2%須保留；不能把全部差額直接當洩漏，需核對取樣、庫存與量測。無實際井壓、鑽進或井控操作。","textEn":"Assume daily liquid feed 1000 t, oil 700 t, water 280 t and unassigned 20 t: closure 98%, unresolved 2%. Do not call the entire residual leakage; check samples, inventory and measurements. No well-pressure, drilling or well-control operations are provided.","sourceIds":["v11x-sleipner","v11x-ccs"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就油氣與CO2物料的「儲層模型與物料平衡」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for reservoir models and material balance in hydrocarbon/co2 balance?","options":["地質資源數量等於可即時開採量。","按給定假想數據覈對流入、流出與庫存。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Geological resources equal immediately producible quantities.","Check inflow, outflow and inventory using assumed data.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"油氣儲層需區分孔隙流體、壓力與連通；累計產量與可採資源不同。 按給定假想數據覈對流入、流出與庫存。","explanationEn":"Reservoirs distinguish pore fluids, pressure and connectivity; cumulative production differs from recoverable resources. Check inflow, outflow and inventory using assumed data."}},{"id":"v11-sleipner-ccs-v11-03","order":3,"sequence":3,"title":"井筒屏障與完整性：架構分析","titleEn":"Well barriers and integrity: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-02"],"objective":"針對井筒完整性概念提出可反駁的井筒屏障與完整性模型與驗證紀錄。","objectiveEn":"Produce a falsifiable well barriers and integrity model and evidence record for well-integrity concepts.","instruction":"在「Sleipner 油氣與碳封存」的師傅示意與公開來源中，先辨識井筒完整性概念。多個屏障路徑與監測共同支持完整性；概念課不提供鑽井或井控操作參數。 建立井筒屏障與完整性的輸入、狀態、輸出及邊界圖；本課重點是分離、壓縮與封存監測邊界。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。用原創功能圖區分承壓路徑與監測，不設計現場操作。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify well-integrity concepts in the mentor diagram and primary sources for Sleipner oil/gas and carbon storage. Multiple barriers/monitoring support integrity; conceptual courses supply no drilling or well-control settings. Draw the inputs, states, outputs and boundaries of well barriers and integrity, focusing on separation, compression and storage-monitoring boundaries. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate containment and monitoring in an original functional diagram without field operations. Record units, undisclosed parameters and model breakdown conditions.","observation":"用原創功能圖區分承壓路徑與監測，不設計現場操作。","observationEn":"Separate containment and monitoring in an original functional diagram without field operations.","failure":"常見誤判：一項井口量測足以證明所有地下屏障。","failureEn":"Common misconception: One wellhead measurement proves every subsurface barrier.","check":"提交井筒完整性概念的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for well-integrity concepts.","knowledge":[{"id":"v11-sleipner-ccs-v11-03-k1","title":"井筒屏障與完整性","titleEn":"Well barriers and integrity","text":"多個屏障路徑與監測共同支持完整性；概念課不提供鑽井或井控操作參數。 本課架構對應：井筒完整性概念","textEn":"Multiple barriers/monitoring support integrity; conceptual courses supply no drilling or well-control settings. Course architecture correspondence: Well-integrity concepts","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用原創功能圖區分承壓路徑與監測，不設計現場操作。 應逐項保留基準與不確定度；一項井口量測足以證明所有地下屏障。 是本單元要排除的誤解。","textEn":"Separate containment and monitoring in an original functional diagram without field operations. Retain each reference and uncertainty; reject the misconception: One wellhead measurement proves every subsurface barrier.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就井筒完整性概念的「井筒屏障與完整性」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for well barriers and integrity in well-integrity concepts?","options":["一項井口量測足以證明所有地下屏障。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","多個屏障路徑與監測共同支持完整性；概念課不提供鑽井或井控操作參數。"],"optionsEn":["One wellhead measurement proves every subsurface barrier.","Equal case averages rule out spatial, temporal and model errors.","Multiple barriers/monitoring support integrity; conceptual courses supply no drilling or well-control settings."],"answer":2,"explanation":"多個屏障路徑與監測共同支持完整性；概念課不提供鑽井或井控操作參數。 用原創功能圖區分承壓路徑與監測，不設計現場操作。","explanationEn":"Multiple barriers/monitoring support integrity; conceptual courses supply no drilling or well-control settings. Separate containment and monitoring in an original functional diagram without field operations."}},{"id":"v11-sleipner-ccs-v11-04","order":4,"sequence":4,"title":"井筒屏障與完整性：證據驗證","titleEn":"Well barriers and integrity: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-03"],"objective":"針對井筒完整性概念提出可反駁的井筒屏障與完整性模型與驗證紀錄。","objectiveEn":"Produce a falsifiable well barriers and integrity model and evidence record for well-integrity concepts.","instruction":"沿用前一步「井筒屏障與完整性」模型，檢查井筒完整性概念的兩個假想案例。用原創功能圖區分承壓路徑與監測，不設計現場操作。 先訂可接受誤差，再比較預測與獨立計算；區分多個屏障路徑與監測共同支持完整性；概念課不提供鑽井或井控操作參數。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous well barriers and integrity model to inspect two hypothetical cases involving well-integrity concepts. Separate containment and monitoring in an original functional diagram without field operations. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Multiple barriers/monitoring support integrity; conceptual courses supply no drilling or well-control settings.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"用原創功能圖區分承壓路徑與監測，不設計現場操作。","observationEn":"Separate containment and monitoring in an original functional diagram without field operations.","failure":"常見誤判：一項井口量測足以證明所有地下屏障。","failureEn":"Common misconception: One wellhead measurement proves every subsurface barrier.","check":"提交井筒完整性概念的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for well-integrity concepts.","knowledge":[{"id":"v11-sleipner-ccs-v11-04-k1","title":"井筒屏障與完整性","titleEn":"Well barriers and integrity","text":"多個屏障路徑與監測共同支持完整性；概念課不提供鑽井或井控操作參數。 本課架構對應：井筒完整性概念","textEn":"Multiple barriers/monitoring support integrity; conceptual courses supply no drilling or well-control settings. Course architecture correspondence: Well-integrity concepts","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用原創功能圖區分承壓路徑與監測，不設計現場操作。 應逐項保留基準與不確定度；一項井口量測足以證明所有地下屏障。 是本單元要排除的誤解。","textEn":"Separate containment and monitoring in an original functional diagram without field operations. Retain each reference and uncertainty; reject the misconception: One wellhead measurement proves every subsurface barrier.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就井筒完整性概念的「井筒屏障與完整性」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for well barriers and integrity in well-integrity concepts?","options":["用原創功能圖區分承壓路徑與監測，不設計現場操作。","一項井口量測足以證明所有地下屏障。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Separate containment and monitoring in an original functional diagram without field operations.","One wellhead measurement proves every subsurface barrier.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"多個屏障路徑與監測共同支持完整性；概念課不提供鑽井或井控操作參數。 用原創功能圖區分承壓路徑與監測，不設計現場操作。","explanationEn":"Multiple barriers/monitoring support integrity; conceptual courses supply no drilling or well-control settings. Separate containment and monitoring in an original functional diagram without field operations."}}]},{"id":"v11-sleipner-ccs-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在Sleipner 油氣與碳封存案例中比較分離與輸送相態與處理與儲層界面，各完成分析及驗證。","descriptionEn":"Analyze and validate separation/transport phases and processing/reservoir interfaces within the Sleipner oil/gas and carbon storage case.","steps":[{"id":"v11-sleipner-ccs-v11-05","order":1,"sequence":5,"title":"多相輸送與壓降：架構分析","titleEn":"Multiphase transport and pressure drop: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-04"],"objective":"針對分離與輸送相態提出可反駁的多相輸送與壓降模型與驗證紀錄。","objectiveEn":"Produce a falsifiable multiphase transport and pressure drop model and evidence record for separation/transport phases.","instruction":"在「Sleipner 油氣與碳封存」的師傅示意與公開來源中，先辨識分離與輸送相態。氣液相分佈影響流動及設備負載；單相近似只適合指定假設。 建立多相輸送與壓降的輸入、狀態、輸出及邊界圖；本課重點是分離、壓縮與封存監測邊界。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較假想單相與兩相情境的模型失配。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify separation/transport phases in the mentor diagram and primary sources for Sleipner oil/gas and carbon storage. Gas/liquid distributions affect flow/loading; single-phase approximations need bounded assumptions. Draw the inputs, states, outputs and boundaries of multiphase transport and pressure drop, focusing on separation, compression and storage-monitoring boundaries. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare single/two-phase assumed cases for model mismatch. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較假想單相與兩相情境的模型失配。","observationEn":"Compare single/two-phase assumed cases for model mismatch.","failure":"常見誤判：油氣水混合流可不加說明地當作純水。","failureEn":"Common misconception: Oil/gas/water mixtures are indistinguishable from pure water without qualification.","check":"提交分離與輸送相態的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for separation/transport phases.","knowledge":[{"id":"v11-sleipner-ccs-v11-05-k1","title":"多相輸送與壓降","titleEn":"Multiphase transport and pressure drop","text":"氣液相分佈影響流動及設備負載；單相近似只適合指定假設。 本課架構對應：分離與輸送相態","textEn":"Gas/liquid distributions affect flow/loading; single-phase approximations need bounded assumptions. Course architecture correspondence: Separation/transport phases","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較假想單相與兩相情境的模型失配。 應逐項保留基準與不確定度；油氣水混合流可不加說明地當作純水。 是本單元要排除的誤解。","textEn":"Compare single/two-phase assumed cases for model mismatch. Retain each reference and uncertainty; reject the misconception: Oil/gas/water mixtures are indistinguishable from pure water without qualification.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就分離與輸送相態的「多相輸送與壓降」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for multiphase transport and pressure drop in separation/transport phases?","options":["油氣水混合流可不加說明地當作純水。","氣液相分佈影響流動及設備負載；單相近似只適合指定假設。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Oil/gas/water mixtures are indistinguishable from pure water without qualification.","Gas/liquid distributions affect flow/loading; single-phase approximations need bounded assumptions.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"氣液相分佈影響流動及設備負載；單相近似只適合指定假設。 比較假想單相與兩相情境的模型失配。","explanationEn":"Gas/liquid distributions affect flow/loading; single-phase approximations need bounded assumptions. Compare single/two-phase assumed cases for model mismatch."}},{"id":"v11-sleipner-ccs-v11-06","order":2,"sequence":6,"title":"多相輸送與壓降：證據驗證","titleEn":"Multiphase transport and pressure drop: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-05"],"objective":"針對分離與輸送相態提出可反駁的多相輸送與壓降模型與驗證紀錄。","objectiveEn":"Produce a falsifiable multiphase transport and pressure drop model and evidence record for separation/transport phases.","instruction":"沿用前一步「多相輸送與壓降」模型，檢查分離與輸送相態的兩個假想案例。比較假想單相與兩相情境的模型失配。 先訂可接受誤差，再比較預測與獨立計算；區分氣液相分佈影響流動及設備負載；單相近似只適合指定假設。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous multiphase transport and pressure drop model to inspect two hypothetical cases involving separation/transport phases. Compare single/two-phase assumed cases for model mismatch. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Gas/liquid distributions affect flow/loading; single-phase approximations need bounded assumptions.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較假想單相與兩相情境的模型失配。","observationEn":"Compare single/two-phase assumed cases for model mismatch.","failure":"常見誤判：油氣水混合流可不加說明地當作純水。","failureEn":"Common misconception: Oil/gas/water mixtures are indistinguishable from pure water without qualification.","check":"提交分離與輸送相態的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for separation/transport phases.","knowledge":[{"id":"v11-sleipner-ccs-v11-06-k1","title":"多相輸送與壓降","titleEn":"Multiphase transport and pressure drop","text":"氣液相分佈影響流動及設備負載；單相近似只適合指定假設。 本課架構對應：分離與輸送相態","textEn":"Gas/liquid distributions affect flow/loading; single-phase approximations need bounded assumptions. Course architecture correspondence: Separation/transport phases","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較假想單相與兩相情境的模型失配。 應逐項保留基準與不確定度；油氣水混合流可不加說明地當作純水。 是本單元要排除的誤解。","textEn":"Compare single/two-phase assumed cases for model mismatch. Retain each reference and uncertainty; reject the misconception: Oil/gas/water mixtures are indistinguishable from pure water without qualification.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就分離與輸送相態的「多相輸送與壓降」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for multiphase transport and pressure drop in separation/transport phases?","options":["油氣水混合流可不加說明地當作純水。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較假想單相與兩相情境的模型失配。"],"optionsEn":["Oil/gas/water mixtures are indistinguishable from pure water without qualification.","Equal case averages rule out spatial, temporal and model errors.","Compare single/two-phase assumed cases for model mismatch."],"answer":2,"explanation":"氣液相分佈影響流動及設備負載；單相近似只適合指定假設。 比較假想單相與兩相情境的模型失配。","explanationEn":"Gas/liquid distributions affect flow/loading; single-phase approximations need bounded assumptions. Compare single/two-phase assumed cases for model mismatch."}},{"id":"v11-sleipner-ccs-v11-07","order":3,"sequence":7,"title":"海底連接與平臺：架構分析","titleEn":"Subsea links and platforms: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-06"],"objective":"針對處理與儲層界面提出可反駁的海底連接與平臺模型與驗證紀錄。","objectiveEn":"Produce a falsifiable subsea links and platforms model and evidence record for processing/reservoir interfaces.","instruction":"在「Sleipner 油氣與碳封存」的師傅示意與公開來源中，先辨識處理與儲層界面。立管、海底設備與上部處理各有壓力、運動及可維修邊界。 建立海底連接與平臺的輸入、狀態、輸出及邊界圖；本課重點是分離、壓縮與封存監測邊界。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。畫平臺—海底接口並標海況及維護假設。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify processing/reservoir interfaces in the mentor diagram and primary sources for Sleipner oil/gas and carbon storage. Risers, subsea systems and topsides have distinct pressure, motion and serviceability boundaries. Draw the inputs, states, outputs and boundaries of subsea links and platforms, focusing on separation, compression and storage-monitoring boundaries. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Draw platform/subsea interfaces with environmental/service assumptions. Record units, undisclosed parameters and model breakdown conditions.","observation":"畫平臺—海底接口並標海況及維護假設。","observationEn":"Draw platform/subsea interfaces with environmental/service assumptions.","failure":"常見誤判：平臺穩定證明海底所有部件沒有動態負載。","failureEn":"Common misconception: Platform stability proves no dynamic load on subsea components.","check":"提交處理與儲層界面的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for processing/reservoir interfaces.","knowledge":[{"id":"v11-sleipner-ccs-v11-07-k1","title":"海底連接與平臺","titleEn":"Subsea links and platforms","text":"立管、海底設備與上部處理各有壓力、運動及可維修邊界。 本課架構對應：處理與儲層界面","textEn":"Risers, subsea systems and topsides have distinct pressure, motion and serviceability boundaries. Course architecture correspondence: Processing/reservoir interfaces","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫平臺—海底接口並標海況及維護假設。 應逐項保留基準與不確定度；平臺穩定證明海底所有部件沒有動態負載。 是本單元要排除的誤解。","textEn":"Draw platform/subsea interfaces with environmental/service assumptions. Retain each reference and uncertainty; reject the misconception: Platform stability proves no dynamic load on subsea components.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就處理與儲層界面的「海底連接與平臺」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for subsea links and platforms in processing/reservoir interfaces?","options":["立管、海底設備與上部處理各有壓力、運動及可維修邊界。","平臺穩定證明海底所有部件沒有動態負載。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Risers, subsea systems and topsides have distinct pressure, motion and serviceability boundaries.","Platform stability proves no dynamic load on subsea components.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"立管、海底設備與上部處理各有壓力、運動及可維修邊界。 畫平臺—海底接口並標海況及維護假設。","explanationEn":"Risers, subsea systems and topsides have distinct pressure, motion and serviceability boundaries. Draw platform/subsea interfaces with environmental/service assumptions."}},{"id":"v11-sleipner-ccs-v11-08","order":4,"sequence":8,"title":"海底連接與平臺：證據驗證","titleEn":"Subsea links and platforms: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-07"],"objective":"針對處理與儲層界面提出可反駁的海底連接與平臺模型與驗證紀錄。","objectiveEn":"Produce a falsifiable subsea links and platforms model and evidence record for processing/reservoir interfaces.","instruction":"沿用前一步「海底連接與平臺」模型，檢查處理與儲層界面的兩個假想案例。畫平臺—海底接口並標海況及維護假設。 先訂可接受誤差，再比較預測與獨立計算；區分立管、海底設備與上部處理各有壓力、運動及可維修邊界。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous subsea links and platforms model to inspect two hypothetical cases involving processing/reservoir interfaces. Draw platform/subsea interfaces with environmental/service assumptions. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Risers, subsea systems and topsides have distinct pressure, motion and serviceability boundaries.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"畫平臺—海底接口並標海況及維護假設。","observationEn":"Draw platform/subsea interfaces with environmental/service assumptions.","failure":"常見誤判：平臺穩定證明海底所有部件沒有動態負載。","failureEn":"Common misconception: Platform stability proves no dynamic load on subsea components.","check":"提交處理與儲層界面的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for processing/reservoir interfaces.","knowledge":[{"id":"v11-sleipner-ccs-v11-08-k1","title":"海底連接與平臺","titleEn":"Subsea links and platforms","text":"立管、海底設備與上部處理各有壓力、運動及可維修邊界。 本課架構對應：處理與儲層界面","textEn":"Risers, subsea systems and topsides have distinct pressure, motion and serviceability boundaries. Course architecture correspondence: Processing/reservoir interfaces","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫平臺—海底接口並標海況及維護假設。 應逐項保留基準與不確定度；平臺穩定證明海底所有部件沒有動態負載。 是本單元要排除的誤解。","textEn":"Draw platform/subsea interfaces with environmental/service assumptions. Retain each reference and uncertainty; reject the misconception: Platform stability proves no dynamic load on subsea components.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就處理與儲層界面的「海底連接與平臺」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for subsea links and platforms in processing/reservoir interfaces?","options":["平臺穩定證明海底所有部件沒有動態負載。","畫平臺—海底接口並標海況及維護假設。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Platform stability proves no dynamic load on subsea components.","Draw platform/subsea interfaces with environmental/service assumptions.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"立管、海底設備與上部處理各有壓力、運動及可維修邊界。 畫平臺—海底接口並標海況及維護假設。","explanationEn":"Risers, subsea systems and topsides have distinct pressure, motion and serviceability boundaries. Draw platform/subsea interfaces with environmental/service assumptions."}}]},{"id":"v11-sleipner-ccs-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在Sleipner 油氣與碳封存案例中比較capture能耗與減排與封存monitoring與不確定度，各完成分析及驗證。","descriptionEn":"Analyze and validate capture energy/abatement and storage monitoring/uncertainty within the Sleipner oil/gas and carbon storage case.","steps":[{"id":"v11-sleipner-ccs-v11-09","order":1,"sequence":9,"title":"處理能量與排放：架構分析","titleEn":"Processing energy and emissions: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-08"],"objective":"針對capture能耗與減排提出可反駁的處理能量與排放模型與驗證紀錄。","objectiveEn":"Produce a falsifiable processing energy and emissions model and evidence record for capture energy/abatement.","instruction":"在「Sleipner 油氣與碳封存」的師傅示意與公開來源中，先辨識capture能耗與減排。分離、壓縮與冷卻消耗能量；岸電改變部分排放邊界而不使全生命週期零排放。 建立處理能量與排放的輸入、狀態、輸出及邊界圖；本課重點是分離、壓縮與封存監測邊界。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。分開現場、外購電與生命週期假想排放。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify capture energy/abatement in the mentor diagram and primary sources for Sleipner oil/gas and carbon storage. Separation, compression and cooling use energy; shore power shifts some emissions without making lifecycle emissions zero. Draw the inputs, states, outputs and boundaries of processing energy and emissions, focusing on separation, compression and storage-monitoring boundaries. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate onsite, purchased-power and lifecycle assumed emissions. Record units, undisclosed parameters and model breakdown conditions.","observation":"分開現場、外購電與生命週期假想排放。","observationEn":"Separate onsite, purchased-power and lifecycle assumed emissions.","failure":"常見誤判：岸電必然等於整個油氣產品零排放。","failureEn":"Common misconception: Shore power means zero lifecycle emissions for oil/gas products.","check":"提交capture能耗與減排的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for capture energy/abatement.","knowledge":[{"id":"v11-sleipner-ccs-v11-09-k1","title":"處理能量與排放","titleEn":"Processing energy and emissions","text":"分離、壓縮與冷卻消耗能量；岸電改變部分排放邊界而不使全生命週期零排放。 本課架構對應：capture能耗與減排","textEn":"Separation, compression and cooling use energy; shore power shifts some emissions without making lifecycle emissions zero. Course architecture correspondence: Capture energy/abatement","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開現場、外購電與生命週期假想排放。 應逐項保留基準與不確定度；岸電必然等於整個油氣產品零排放。 是本單元要排除的誤解。","textEn":"Separate onsite, purchased-power and lifecycle assumed emissions. Retain each reference and uncertainty; reject the misconception: Shore power means zero lifecycle emissions for oil/gas products.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就capture能耗與減排的「處理能量與排放」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for processing energy and emissions in capture energy/abatement?","options":["岸電必然等於整個油氣產品零排放。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","分離、壓縮與冷卻消耗能量；岸電改變部分排放邊界而不使全生命週期零排放。"],"optionsEn":["Shore power means zero lifecycle emissions for oil/gas products.","Equal case averages rule out spatial, temporal and model errors.","Separation, compression and cooling use energy; shore power shifts some emissions without making lifecycle emissions zero."],"answer":2,"explanation":"分離、壓縮與冷卻消耗能量；岸電改變部分排放邊界而不使全生命週期零排放。 分開現場、外購電與生命週期假想排放。","explanationEn":"Separation, compression and cooling use energy; shore power shifts some emissions without making lifecycle emissions zero. Separate onsite, purchased-power and lifecycle assumed emissions."}},{"id":"v11-sleipner-ccs-v11-10","order":2,"sequence":10,"title":"處理能量與排放：證據驗證","titleEn":"Processing energy and emissions: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-09"],"objective":"針對capture能耗與減排提出可反駁的處理能量與排放模型與驗證紀錄。","objectiveEn":"Produce a falsifiable processing energy and emissions model and evidence record for capture energy/abatement.","instruction":"沿用前一步「處理能量與排放」模型，檢查capture能耗與減排的兩個假想案例。分開現場、外購電與生命週期假想排放。 先訂可接受誤差，再比較預測與獨立計算；區分分離、壓縮與冷卻消耗能量；岸電改變部分排放邊界而不使全生命週期零排放。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous processing energy and emissions model to inspect two hypothetical cases involving capture energy/abatement. Separate onsite, purchased-power and lifecycle assumed emissions. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Separation, compression and cooling use energy; shore power shifts some emissions without making lifecycle emissions zero.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"分開現場、外購電與生命週期假想排放。","observationEn":"Separate onsite, purchased-power and lifecycle assumed emissions.","failure":"常見誤判：岸電必然等於整個油氣產品零排放。","failureEn":"Common misconception: Shore power means zero lifecycle emissions for oil/gas products.","check":"提交capture能耗與減排的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for capture energy/abatement.","knowledge":[{"id":"v11-sleipner-ccs-v11-10-k1","title":"處理能量與排放","titleEn":"Processing energy and emissions","text":"分離、壓縮與冷卻消耗能量；岸電改變部分排放邊界而不使全生命週期零排放。 本課架構對應：capture能耗與減排","textEn":"Separation, compression and cooling use energy; shore power shifts some emissions without making lifecycle emissions zero. Course architecture correspondence: Capture energy/abatement","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開現場、外購電與生命週期假想排放。 應逐項保留基準與不確定度；岸電必然等於整個油氣產品零排放。 是本單元要排除的誤解。","textEn":"Separate onsite, purchased-power and lifecycle assumed emissions. Retain each reference and uncertainty; reject the misconception: Shore power means zero lifecycle emissions for oil/gas products.","sourceIds":["v11x-sleipner","v11x-ccs"]}],"quiz":{"question":"就capture能耗與減排的「處理能量與排放」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for processing energy and emissions in capture energy/abatement?","options":["分開現場、外購電與生命週期假想排放。","岸電必然等於整個油氣產品零排放。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Separate onsite, purchased-power and lifecycle assumed emissions.","Shore power means zero lifecycle emissions for oil/gas products.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"分離、壓縮與冷卻消耗能量；岸電改變部分排放邊界而不使全生命週期零排放。 分開現場、外購電與生命週期假想排放。","explanationEn":"Separation, compression and cooling use energy; shore power shifts some emissions without making lifecycle emissions zero. Separate onsite, purchased-power and lifecycle assumed emissions."}},{"id":"v11-sleipner-ccs-v11-11","order":3,"sequence":11,"title":"監測停機與復原：架構分析","titleEn":"Monitoring, shutdown and recovery: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-10"],"objective":"針對封存monitoring與不確定度提出可反駁的監測停機與復原模型與驗證紀錄。","objectiveEn":"Produce a falsifiable monitoring, shutdown and recovery model and evidence record for storage monitoring/uncertainty.","instruction":"在「Sleipner 油氣與碳封存」的師傅示意與公開來源中，先辨識封存monitoring與不確定度。可用率受維護、完整性與供能限制；只做公開報告和假想事件分析。 建立監測停機與復原的輸入、狀態、輸出及邊界圖；本課重點是分離、壓縮與封存監測邊界。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。在離線事件表比較停機、恢復及泄漏證據鏈。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify storage monitoring/uncertainty in the mentor diagram and primary sources for Sleipner oil/gas and carbon storage. Maintenance, integrity and energy affect availability; analyze public reports/assumed events only. Draw the inputs, states, outputs and boundaries of monitoring, shutdown and recovery, focusing on separation, compression and storage-monitoring boundaries. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare downtime, recovery and containment evidence in an offline event table. Record units, undisclosed parameters and model breakdown conditions.","observation":"在離線事件表比較停機、恢復及泄漏證據鏈。","observationEn":"Compare downtime, recovery and containment evidence in an offline event table.","failure":"常見誤判：恢復產量本身就證明所有安全狀態均正確。","failureEn":"Common misconception: Recovered production proves every safety state correct.","check":"提交封存monitoring與不確定度的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for storage monitoring/uncertainty.","knowledge":[{"id":"v11-sleipner-ccs-v11-11-k1","title":"監測停機與復原","titleEn":"Monitoring, shutdown and recovery","text":"可用率受維護、完整性與供能限制；只做公開報告和假想事件分析。 本課架構對應：封存monitoring與不確定度","textEn":"Maintenance, integrity and energy affect availability; analyze public reports/assumed events only. Course architecture correspondence: Storage monitoring/uncertainty","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"在離線事件表比較停機、恢復及泄漏證據鏈。 應逐項保留基準與不確定度；恢復產量本身就證明所有安全狀態均正確。 是本單元要排除的誤解。","textEn":"Compare downtime, recovery and containment evidence in an offline event table. Retain each reference and uncertainty; reject the misconception: Recovered production proves every safety state correct.","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想一日液體進料1000 t，油700 t、水280 t、未判明20 t。質量閉合=98%，未判明2%須保留；不能把全部差額直接當洩漏，需核對取樣、庫存與量測。無實際井壓、鑽進或井控操作。","textEn":"Assume daily liquid feed 1000 t, oil 700 t, water 280 t and unassigned 20 t: closure 98%, unresolved 2%. Do not call the entire residual leakage; check samples, inventory and measurements. No well-pressure, drilling or well-control operations are provided.","sourceIds":["v11x-sleipner","v11x-ccs"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就封存monitoring與不確定度的「監測停機與復原」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for monitoring, shutdown and recovery in storage monitoring/uncertainty?","options":["恢復產量本身就證明所有安全狀態均正確。","可用率受維護、完整性與供能限制；只做公開報告和假想事件分析。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Recovered production proves every safety state correct.","Maintenance, integrity and energy affect availability; analyze public reports/assumed events only.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"可用率受維護、完整性與供能限制；只做公開報告和假想事件分析。 在離線事件表比較停機、恢復及泄漏證據鏈。","explanationEn":"Maintenance, integrity and energy affect availability; analyze public reports/assumed events only. Compare downtime, recovery and containment evidence in an offline event table."}},{"id":"v11-sleipner-ccs-v11-12","order":4,"sequence":12,"title":"監測停機與復原：證據驗證","titleEn":"Monitoring, shutdown and recovery: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-sleipner","v11x-ccs"],"prerequisiteIds":["v11-sleipner-ccs-v11-11"],"objective":"針對封存monitoring與不確定度提出可反駁的監測停機與復原模型與驗證紀錄。","objectiveEn":"Produce a falsifiable monitoring, shutdown and recovery model and evidence record for storage monitoring/uncertainty.","instruction":"沿用前一步「監測停機與復原」模型，檢查封存monitoring與不確定度的兩個假想案例。在離線事件表比較停機、恢復及泄漏證據鏈。 先訂可接受誤差，再比較預測與獨立計算；區分可用率受維護、完整性與供能限制；只做公開報告和假想事件分析。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous monitoring, shutdown and recovery model to inspect two hypothetical cases involving storage monitoring/uncertainty. Compare downtime, recovery and containment evidence in an offline event table. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Maintenance, integrity and energy affect availability; analyze public reports/assumed events only.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"在離線事件表比較停機、恢復及泄漏證據鏈。","observationEn":"Compare downtime, recovery and containment evidence in an offline event table.","failure":"常見誤判：恢復產量本身就證明所有安全狀態均正確。","failureEn":"Common misconception: Recovered production proves every safety state correct.","check":"提交封存monitoring與不確定度的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for storage monitoring/uncertainty.","knowledge":[{"id":"v11-sleipner-ccs-v11-12-k1","title":"監測停機與復原","titleEn":"Monitoring, shutdown and recovery","text":"可用率受維護、完整性與供能限制；只做公開報告和假想事件分析。 本課架構對應：封存monitoring與不確定度","textEn":"Maintenance, integrity and energy affect availability; analyze public reports/assumed events only. Course architecture correspondence: Storage monitoring/uncertainty","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"在離線事件表比較停機、恢復及泄漏證據鏈。 應逐項保留基準與不確定度；恢復產量本身就證明所有安全狀態均正確。 是本單元要排除的誤解。","textEn":"Compare downtime, recovery and containment evidence in an offline event table. Retain each reference and uncertainty; reject the misconception: Recovered production proves every safety state correct.","sourceIds":["v11x-sleipner","v11x-ccs"]},{"id":"v11-sleipner-ccs-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想一日液體進料1000 t，油700 t、水280 t、未判明20 t。質量閉合=98%，未判明2%須保留；不能把全部差額直接當洩漏，需核對取樣、庫存與量測。無實際井壓、鑽進或井控操作。","textEn":"Assume daily liquid feed 1000 t, oil 700 t, water 280 t and unassigned 20 t: closure 98%, unresolved 2%. Do not call the entire residual leakage; check samples, inventory and measurements. No well-pressure, drilling or well-control operations are provided.","sourceIds":["v11x-sleipner","v11x-ccs"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就封存monitoring與不確定度的「監測停機與復原」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for monitoring, shutdown and recovery in storage monitoring/uncertainty?","options":["恢復產量本身就證明所有安全狀態均正確。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","在離線事件表比較停機、恢復及泄漏證據鏈。"],"optionsEn":["Recovered production proves every safety state correct.","Equal case averages rule out spatial, temporal and model errors.","Compare downtime, recovery and containment evidence in an offline event table."],"answer":2,"explanation":"可用率受維護、完整性與供能限制；只做公開報告和假想事件分析。 在離線事件表比較停機、恢復及泄漏證據鏈。","explanationEn":"Maintenance, integrity and energy affect availability; analyze public reports/assumed events only. Compare downtime, recovery and containment evidence in an offline event table."}}]}],"summary":"以分離、壓縮與封存監測邊界解析Sleipner 油氣與碳封存：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore Sleipner oil/gas and carbon storage through separation, compression and storage-monitoring boundaries: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"公開資源工程的離線質量、能量及環境證據判讀；不提供鑽井、井控、採掘、爆破或危險化學浸出SOP。採礦權、許可、地質完整性與現場規範需由合格團隊另行確認，課程完成不是操作資格。","scopeEn":"Offline public resource-engineering material/energy/environmental analysis; no drilling, well-control, excavation, blasting or hazardous-leaching SOP. Qualified teams separately establish rights, permits, integrity and field requirements; completion is not operating qualification.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假想一日液體進料1000 t，油700 t、水280 t、未判明20 t。質量閉合=98%，未判明2%須保留；不能把全部差額直接當洩漏，需核對取樣、庫存與量測。無實際井壓、鑽進或井控操作。","textEn":"Assume daily liquid feed 1000 t, oil 700 t, water 280 t and unassigned 20 t: closure 98%, unresolved 2%. Do not call the entire residual leakage; check samples, inventory and measurements. No well-pressure, drilling or well-control operations are provided.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"power","labels":["油氣與CO2物料","井筒完整性概念","分離與輸送相態","處理與儲層界面","capture能耗與減排","封存monitoring與不確定度"],"labelsEn":["Hydrocarbon/CO2 balance","Well-integrity concepts","Separation/transport phases","Processing/reservoir interfaces","Capture energy/abatement","Storage monitoring/uncertainty"],"original":true,"notToScale":true},"vendorHints":[{"name":"Equinor","nameEn":"Equinor","url":"https://www.equinor.com/energy/sleipner","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-sleipner"]},{"name":"Equinor","nameEn":"Equinor","url":"https://www.equinor.com/energy/carbon-capture-utilisation-and-storage","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-ccs"]}],"architectureNodes":[["儲層","Reservoir"],["井筒與海底連接","Wells/subsea links"],["處理平臺","Processing platform"],["儲運介面","Storage/transfer"],["支援與監測","Support/monitoring"]],"architectureEdges":[[0,1],[1,2],[2,3],[4,1],[4,2]],"architectureFamily":"oil","educationEdition":11,"enrichmentVersion":11}};
